    def separateSquares(self, squares: List[List[int]]) -> float:
        total_area = sum(l * l for _, _, l in squares)
        target_area = total_area / 2.0

        # Sweep-line events: at y, width increases by l; at y + l, width decreases by l
        events = []
        for _, y, l in squares:
            events.append((y, l))
            events.append((y + l, -l))

        events.sort()

        current_area = 0
        current_width = 0
        prev_y = events[0][0]

        for y, dl in events:
            dy = y - prev_y
            if dy > 0:
                area_added = current_width * dy
                if current_area + area_added >= target_area:
                    # Target area falls within this y-interval
                    return float(prev_y + (target_area - current_area) / current_width)
                current_area += area_added

            current_width += dl
            prev_y = y

